import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.Dxeykp0S.js";const u=JSON.parse('{"title":"Day 1 · asyncio：Python 的事件循环","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/01-asyncio.md","filePath":"advanced/01-asyncio.md","lastUpdated":1787141678000}'),c={name:"advanced/01-asyncio.md"};function r(i,e,n,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="day-1-·-asyncio-python-的事件循环" tabindex="-1">Day 1 · asyncio：Python 的事件循环 <a class="header-anchor" href="#day-1-·-asyncio-python-的事件循环" aria-label="Permalink to &quot;Day 1 · asyncio：Python 的事件循环&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>asyncio 是 Python 标准库中的异步 IO 框架，核心模型是单线程、协作式调度与 IO 多路复用。Python 的 <code>async/await</code> 有&quot;函数染色&quot;问题，生态里也长期并存同步/异步两套 API。今天理清这一切，Node.js 对照表可作为补充理解。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>理解协程、事件循环、Task 的概念</li><li>掌握 <code>asyncio.gather</code> / <code>create_task</code> / <code>wait_for</code> 等并发原语</li><li>能识别并避免&quot;在协程里调用阻塞函数&quot;的经典事故</li><li>理解 Python 异步生态（如 httpx）与同步生态的分裂</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.python.org/zh-cn/3/library/asyncio-dev.html" target="_blank" rel="noreferrer">Python 官方：asyncio 开发指南</a></li><li><a href="https://realpython.com/async-io-python/" target="_blank" rel="noreferrer">Real Python: Async IO in Python</a>（经典长文）</li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>Node.js</th><th>asyncio</th></tr></thead><tbody><tr><td><code>async function</code> / <code>await</code></td><td><code>async def</code> / <code>await</code>（几乎一样）</td></tr><tr><td><code>Promise.all()</code></td><td><code>asyncio.gather()</code></td></tr><tr><td><code>Promise.race()</code></td><td><code>asyncio.wait(..., return_when=FIRST_COMPLETED)</code></td></tr><tr><td><code>setTimeout</code></td><td><code>asyncio.sleep()</code></td></tr><tr><td>顶层 await</td><td>不允许，入口是 <code>asyncio.run(main())</code></td></tr><tr><td>一切都是异步的</td><td>同步是默认，异步要显式选库</td></tr><tr><td><code>setImmediate</code> / <code>process.nextTick</code></td><td><code>loop.call_soon()</code></td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>并发抓取器</strong>：用 <code>httpx</code>（异步 HTTP 客户端，对标 axios/got）写一个并发抓取 20 个 URL 的脚本。先用同步 for 循环写一版计时，再用 <code>asyncio.gather</code> 改写，对比耗时。要求加上 <code>asyncio.Semaphore</code> 限制并发数为 5（对标 p-limit）。</p></li><li><p><strong>制造事故</strong>：在协程里调用 <code>time.sleep(3)</code> 而不是 <code>asyncio.sleep(3)</code>，观察并发失效；再调用同步的 <code>requests.get()</code>，体会&quot;一个阻塞调用冻结整个事件循环&quot;。学会用 <code>asyncio.to_thread()</code> 把同步函数安全地包进异步世界。</p></li><li><p><strong>超时与取消</strong>：给任务 1 加上 <code>asyncio.wait_for(coro, timeout=5)</code> 超时控制，处理 <code>asyncio.TimeoutError</code>；再实验 <code>task.cancel()</code>，理解 <code>CancelledError</code> 的传播。</p></li><li><p><strong>异步生成器</strong>：用 <code>async def</code> + <code>yield</code> 写一个异步生成器，模拟流式消费（比如逐行读取 SSE 流），用 <code>async for</code> 消费——这是你以后接 LLM 流式输出的核心技能。</p></li><li><p><strong>（选做）生产者-消费者</strong>：用 <code>asyncio.Queue</code> 实现生产者-消费者模式：3 个生产者产生任务，2 个消费者处理，优雅关闭。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>协程对象、<code>Task</code> 和 <code>Future</code> 在 asyncio 中分别扮演什么角色？</li><li>为什么 <code>asyncio.gather</code> 里的协程是并发的，但 CPU 占用始终是单核？</li><li><code>asyncio.create_task()</code> 和直接 <code>await coro</code> 的区别是什么？</li><li>在 FastAPI 里，<code>def</code> 路由和 <code>async def</code> 路由的执行方式有何不同？（FastAPI 对 def 路由做了什么？）</li><li>Python 的异步库为什么要&quot;另起炉灶&quot;（httpx vs requests）？能不能混用？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://peps.python.org/pep-3156/" target="_blank" rel="noreferrer">PEP 3156：asyncio 的设计</a></li><li><a href="https://journal.stuffwithstuff.com/2015/02/01/what-color-is-your-function/" target="_blank" rel="noreferrer">What Color is Your Function?</a> —— 理解&quot;函数染色&quot;问题的经典文章</li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节直面 <a href="./02-concurrency">GIL 与多进程</a>——Python 并发绕不开的话题，也是面试和性能调优的核心。</p>',18)])])}const p=o(c,[["render",r]]);export{u as __pageData,p as default};
